                                {
                    printf("\033[31m\033[1mProblem with the argument to \"-ION\".\033  1: Zn ; 2: C0 (ca) ; 3: Mg ; 4: Mn ; 5: Fe2+ ; 6: Fe3+ ; 7: Cu ; 8: Co ; 9: CAD (Cd); 10: Ni; Default 1:Zn\n");
                                        exit( 1 );
                                   }

                          if(whationnum!=1&&whationnum!=2&&whationnum!=3&&whationnum!=4&&whationnum!=5&&whationnum!=6&&whationnum!=7&&whationnum!=8&&whationnum!=9&&whationnum!=10)
                {
                    printf("\033[31m\033[1mProblem with the argument to \"-ION\".\033  1: Zn ; 2: C0 (:Ca) ; 3: Mg ; 4: Mn ; 5: Fe2+ ; 6: Fe3+ ; 7: Cu ; 8: Co ; 9: CAD (:cd); 10: Ni\n");
                                        exit( 1 );
                }
