double Cbond(double x1, double y1, double z1,double x2, double y2, double z2)
{
double bond;
bond= sqrt((x2-x1)*(x2-x1)+(y2-y1)*(y2-y1)+(z2-z1)*(z2-z1));
return (bond);
}
double CRMSD(double x1, double y1, double z1,double x2, double y2, double z2)
{
double bond;
bond= (x2-x1)*(x2-x1)+(y2-y1)*(y2-y1)+(z2-z1)*(z2-z1);
return (bond);
}
double  Cangle(  double x1, double y1, double z1,double x2, double y2, double z2,double x3, double y3, double z3 )
{
double angle;
double a,b,c;
       a=sqrt((x2-x3)*(x2-x3)+(y2-y3)*(y2-y3)+(z2-z3)*(z2-z3));
       b=sqrt((x2-x1)*(x2-x1)+(y2-y1)*(y2-y1)+(z2-z1)*(z2-z1));
       c=(x2-x3)*(x2-x1)+(y2-y3)*(y2-y1)+(z2-z3)*(z2-z1);

       angle=acos(c/(a*b));
      return (angle);

}



double Ctorsion( double x1, double y1, double z1,double x2, double y2, double z2,double x3, double y3, double z3,double x4, double y4, double z4)
{
  double ax, ay, az, anorm;
  double bx, by, bz, bnorm;
  double cx, cy, cz;
  double angle;

  VOP_3D_COORDS_CROSS_PRODUCT(     ax,      ay,      az,
                              (x2-x1), (y2-y1), (z2-z1),
                              (x3-x2), (y3-y2), (z3-z2));

  VOP_3D_COORDS_CROSS_PRODUCT(     bx,      by,      bz,
                              (x4-x3), (y4-y3), (z4-z3),
                              (x2-x3), (y2-y3), (z2-z3));

  anorm = sqrt(ax*ax + ay*ay + az*az);
  bnorm = sqrt(bx*bx + by*by + bz*bz);

  VOP_3D_COORDS_CROSS_PRODUCT(cx, cy, cz,
                              ax, ay, az,
                              bx, by, bz);

  angle = (ax*bx + ay*by + az*bz) / (anorm * bnorm);

  if ( angle > 1.0 ) angle = 1.0;
  if ( angle < -1.0 ) angle = -1.0;

  angle = acos( angle );

   angle = 180.0 * angle / M_PI;

  if ( (cx * (x3-x2) + cy * (y3-y2) + cz * (z3-z2)) < 0 )
    angle = -angle;
  return(angle);
}

int cmn(int m, int n)
{
int i;
long int s=1,t=1,p=1;
for(i=1;i<=m;i++)
{
s*=i;
}
for(i=1;i<=(m-n);i++)
{
t*=i;
}
for(i=1;i<=n;i++)
{
p*=i;
}

return(s/(t*p));

}





